// =============================================================
// components/Header/Header.jsx
// Sticky navbar with logo, nav links, CTA buttons, and a
// mobile hamburger drawer.
// =============================================================

import { useState } from 'react';
import { Link, NavLink } from 'react-router-dom';
import Button from '../Button/Button';
import { SITE_CONFIG, getWhatsAppUrl, getPhoneUrl } from '../../config/site';
import logo from '../../assets/logo5.png';//logo.png
import styles from './Header.module.css';

const NAV_LINKS = [
  { label: 'Accueil',          to: '/' },
  { label: 'Services',         to: '/services' },
  { label: 'Transport',        to: '/transport' },
  { label: 'Comment ça marche', to: '/comment-ca-marche' },
  { label: 'Contact',          to: '/contact' },
];

export default function Header() {
  const [drawerOpen, setDrawerOpen] = useState(false);

  const closeDrawer = () => setDrawerOpen(false);

  return (
    <header className={styles.header}>
      {/* ── Main bar ──────────────────────────────────────── */}
      <div className={`container ${styles.inner}`}>

        {/* Logo */}
        <Link to="/" className={styles.logo} onClick={closeDrawer}>
          <img src={logo} alt="PTC Services" className={styles.logoImg} />
          <span className={styles.logoText}>{SITE_CONFIG.name}</span>
        </Link>

        {/* Desktop nav */}
        <nav className={styles.nav} aria-label="Navigation principale">
          {NAV_LINKS.map(({ label, to }) => (
            <NavLink
              key={to}
              to={to}
              end={to === '/'}
              className={({ isActive }) =>
                [styles.navLink, isActive ? styles.active : ''].join(' ')
              }
            >
              {label}
            </NavLink>
          ))}
        </nav>

        {/* Desktop CTAs */}
        <div className={styles.ctaGroup}>
          <Button variant="outline" size="sm" href={getPhoneUrl()}>
            📞 Appeler
          </Button>
          <Button variant="whatsapp" size="sm" href={getWhatsAppUrl()}>
            💬 WhatsApp
          </Button>
        </div>

        {/* Burger (mobile) */}
        <button
          className={[styles.burger, drawerOpen ? styles.open : ''].join(' ')}
          onClick={() => setDrawerOpen((v) => !v)}
          aria-label="Menu"
          aria-expanded={drawerOpen}
        >
          <span />
          <span />
          <span />
        </button>
      </div>

      {/* ── Mobile drawer ─────────────────────────────────── */}
      <div className={[styles.drawer, drawerOpen ? styles.open : ''].join(' ')}>
        {NAV_LINKS.map(({ label, to }) => (
          <NavLink
            key={to}
            to={to}
            end={to === '/'}
            className={styles.drawerLink}
            onClick={closeDrawer}
          >
            {label}
          </NavLink>
        ))}
        <div className={styles.drawerCtas}>
          <Button variant="navy" full href={getPhoneUrl()} onClick={closeDrawer}>
            📞 Appeler maintenant
          </Button>
          <Button variant="whatsapp" full href={getWhatsAppUrl()} onClick={closeDrawer}>
            💬 WhatsApp
          </Button>
        </div>
      </div>
    </header>
  );
}
