// =============================================================
// components/Button/Button.jsx
// Reusable button that handles internal links, external URLs,
// and plain onClick actions.
// Props:
//   variant  — 'primary' | 'outline' | 'navy' | 'whatsapp'
//   size     — 'sm' | 'md' | 'lg'
//   full     — boolean (width: 100%)
//   href     — string  (renders as <a>)
//   onClick  — function
//   children — node
// =============================================================

import styles from './Button.module.css';

export default function Button({
  variant = 'primary',
  size = 'md',
  full = false,
  href,
  onClick,
  children,
  className = '',
  ...rest
}) {
  const classes = [
    styles.btn,
    styles[variant],
    size !== 'md' ? styles[size] : '',
    full ? styles.full : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  // Render as anchor for external/internal links
  if (href) {
    const isExternal = href.startsWith('http') || href.startsWith('tel:') || href.startsWith('https://wa.me');
    return (
      <a
        href={href}
        className={classes}
        target={isExternal ? '_blank' : undefined}
        rel={isExternal ? 'noopener noreferrer' : undefined}
        {...rest}
      >
        {children}
      </a>
    );
  }

  return (
    <button className={classes} onClick={onClick} {...rest}>
      {children}
    </button>
  );
}
