// ── Helper: build WhatsApp URL ─────────────────────────────────
export const getWhatsAppUrl = (customMessage) => {
  const msg = encodeURIComponent(customMessage || SITE_CONFIG.whatsappMessage);
  return `https://wa.me/${SITE_CONFIG.whatsapp}?text=${msg}`;
};

// ── Helper: build phone URL ────────────────────────────────────
export const getPhoneUrl = () => `tel:${SITE_CONFIG.phone}`;
